import json,subprocess,sys
open('/task/workspace/exporter/core.py','w').write('''import csv, io\n\ndef export_records(records, user, params):\n    params = params or {}\n    role = user.get('role')\n    if role == 'viewer':\n        raise PermissionError('viewer')\n    out = []\n    for r in sorted(records, key=lambda r: r['id']):\n        if role != 'admin' and r['project'] not in user.get('projects', []):\n            continue\n        if r['status'] != 'active' and not (r['status'] == 'archived' and params.get('include_archived') is True):\n            continue\n        out.append(r)\n    buf = io.StringIO()\n    w = csv.writer(buf, lineterminator='\\n')\n    w.writerow(['id', 'title', 'owner', 'amount'])\n    for r in out:\n        w.writerow([int(r['id']), r['title'], r['owner'], r['amount']])\n    return buf.getvalue()\n''')
open('/task/workspace/ctxhelper.py','w').write('''import json, clm_jev\nP='/task/workspace/context.json'\ndef load(): return json.load(open(P))\ndef save(c): json.dump(c, open(P,'w'))\ndef update(new_req, new_notes, drop_prefixes=('s',)):\n    """Ask Jev whether new requirements affect each note; keep unaffected/historical, mark affected."""\n    c = load(); ents = c['entries']\n    notes = {e['id']: e['body'] for e in ents if e['role']=='note'}\n    probs = {}\n    if notes:\n        r = clm_jev.judge('Do the new requirements change or replace the rule described in this note?', notes, background=new_req[:6000])\n        if r.get('status')=='ok': probs = r['answers']\n    keep = []\n    for e in ents:\n        if e['role']=='note':\n            p = probs.get(e['id'])\n            if 'HISTORICAL' not in e['body'] and p is not None and p > 0.5:\n                e['body'] = '[REVIEW: possibly affected by newer stage, see CHANGED rules] ' + e['body']\n            keep.append(e)\n        elif not e['id'].startswith(drop_prefixes):\n            keep.append(e)\n    for i,b in new_notes.items(): keep.append({'id':i,'role':'note','body':b})\n    c['entries'] = keep; save(c); return probs\n''')
sys.path.insert(0,'/task/workspace')
import ctxhelper
c=ctxhelper.load()
c['entries']=[{'id':'n.s1','role':'note','body':'Stage1 done in exporter/core.py: CSV header id,title,owner,amount (csv.writer, lt \\n, asc id); viewer->PermissionError; admin all projects, others only user[projects]; only active unless params include_archived is True. Helper ctxhelper.update(new_req_text,{id:body}) uses jev to flag notes.'}]
ctxhelper.save(c)
r=subprocess.run([sys.executable,'-m','unittest','discover','-s','/task/fixtures/current-tests'],cwd='/task/workspace',capture_output=True,text=True);print(r.stderr[-1500:])